	@Test
	void rebuildsLegacyRefCountVersionMarkerFromLiveOwners() throws Exception {
		Path store = copyReleasedStore("legacy-ref-count-version");
		createDatabasePrefix(store.resolve("values"), "ref_counts");
		long subjectId = LmdbCompatibilityFixtures.findReferenceId(store, ValueIds.T_URI,
				"subject".getBytes(StandardCharsets.UTF_8));
		byte[] subjectPayload = LmdbCompatibilityFixtures.nativeGet(store, null,
				LmdbCompatibilityFixtures.idKey(subjectId));
		long namespaceId = Varint.readUnsigned(ByteBuffer.wrap(subjectPayload), 1);
		LmdbCompatibilityFixtures.nativePut(store, "ref_counts", new byte[] { 0 }, new byte[] { 1 });
		LmdbCompatibilityFixtures.nativePut(store, "ref_counts", LmdbCompatibilityFixtures.idKey(subjectId),
				new byte[] { 99 });
		LmdbCompatibilityFixtures.nativePut(store, "ref_counts", LmdbCompatibilityFixtures.idKey(namespaceId),
				new byte[] { 99 });

		assertReadableWritableAndReopen(store, "legacy-ref-count-version", true);

		assertThat(LmdbCompatibilityFixtures.nativeGet(store, "ref_counts",
				LmdbCompatibilityFixtures.idKey(subjectId)))
						.as("ordinary statement ownership does not create dictionary-component references")
						.isNull();
		assertThat(LmdbCompatibilityFixtures.nativeGet(store, "ref_counts",
				LmdbCompatibilityFixtures.idKey(namespaceId)))
						.as("the active subject and predicate both retain their shared namespace")
						.containsExactly(new byte[] { 2 });
	}

